<?php
declare(strict_types=1);
require_once __DIR__.'/ecosystem-core.php';
function eco_products():array{$file=dirname(__DIR__).'/noa-products.json';$base=is_file($file)?json_decode(file_get_contents($file),true,32,JSON_THROW_ON_ERROR):[];$custom=ns_doc('ecosystem:products')['data']['items']??[];$out=[];foreach(array_merge($base,$custom)as $p)$out[$p['id']]=$p;return array_values(array_filter($out,fn($p)=>empty($p['hidden'])));}
function eco_product(string $id):array{foreach(eco_products()as $p)if($p['id']===$id)return $p;throw new DomainException('product_unavailable');}
function eco_shop(array $a):array{$r=$a['id']!==''?ns_doc('ecosystem:shop:'.hash('sha256',$a['id'])):null;$v=$r['data']??['wishlist'=>[],'cart'=>[]];$products=eco_products();$ids=array_column($products,'id');$v['wishlist']=array_values(array_intersect($v['wishlist'],$ids));$v['cart']=array_values(array_filter($v['cart'],fn($x)=>in_array($x['id'],$ids,true)));return ['products'=>$products,'state'=>$v,'revision'=>$r['revision']??0,'storeUrl'=>'https://marpple.shop/kr/jr_lifestyle','checkoutMode'=>'official-product-link'];}
function eco_shop_save(array $a,array $b):array{eco_require($a);return ns_atomic($a['id'],false,function()use($a,$b){$key='ecosystem:shop:'.hash('sha256',$a['id']);$r=ns_doc($key,true);if(($b['revision']??null)!==($r['revision']??0))throw new DomainException('revision_conflict');$wishlist=$b['wishlist']??[];$cart=$b['cart']??[];if(!is_array($wishlist)||count($wishlist)>100||!is_array($cart)||count($cart)>50)throw new InvalidArgumentException('invalid_cart');foreach($wishlist as $id)eco_product(eco_text($id,80,true));$seen=[];foreach($cart as &$x){$id=eco_text($x['id']??'',80,true);eco_product($id);if(isset($seen[$id])||!is_int($x['quantity']??null)||$x['quantity']<1||$x['quantity']>10)throw new InvalidArgumentException('invalid_cart');$seen[$id]=true;$x=['id'=>$id,'quantity'=>$x['quantity'],'optionNote'=>eco_text($x['optionNote']??'',200)];}unset($x);$v=['wishlist'=>array_values(array_unique($wishlist)),'cart'=>array_values($cart)];$revision=ns_put($key,'ecosystem_shop',$v,$r['revision']??0,$a['id']);return ['state'=>$v,'revision'=>$revision];});}
function eco_product_save(array $a,array $b):array{if(!$a['admin'])throw new DomainException('administrator_required');$id=eco_text($b['id']??'',80,true);if(!preg_match('/^[a-z0-9_-]+$/D',$id))throw new InvalidArgumentException('invalid_id');$p=['id'=>$id];foreach(['title'=>120,'description'=>3000,'category'=>40]as $k=>$max)$p[$k]=eco_text($b[$k]??'',$max,true);$url=eco_text($b['url']??'',500,true);if(!preg_match('~^https://marpple\.shop/kr/jr_lifestyle/products/[0-9]+$~D',$url))throw new InvalidArgumentException('official_product_url_required');$p['url']=$url;$price=$b['priceWon']??null;if(!is_int($price)||$price<1||$price>100000000)throw new InvalidArgumentException('invalid_price');$p['priceWon']=$price;$image=eco_text($b['image']??'',200,true);if(!preg_match('~^/noa-assets/ecosystem/[a-z0-9_-]+\.(webp|jpg|png)$~D',$image))throw new InvalidArgumentException('approved_image_required');$p['image']=$image;$p['checkedAt']=date('Y-m-d');$p['hidden']=!empty($b['hidden']);return ns_atomic('ecosystem:products',false,function()use($a,$p){$r=ns_doc('ecosystem:products',true);$items=$r['data']['items']??[];$items=array_values(array_filter($items,fn($x)=>$x['id']!==$p['id']));$items[]=$p;ns_put('ecosystem:products','ecosystem_products',['items'=>$items],$r['revision']??0,$a['id']);return ['product'=>$p];});}
